import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"mKCP Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/protocols/mkcp.md","filePath":"en/development/protocols/mkcp.md","lastUpdated":1769207840000}`),a={name:`en/development/protocols/mkcp.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="mkcp-protocol" tabindex="-1">mKCP Protocol <a class="header-anchor" href="#mkcp-protocol" aria-label="Permalink to “mKCP Protocol”">​</a></h1><p>mKCP is a stream transport protocol, modified from the <a href="https://github.com/skywind3000/kcp" target="_blank" rel="noreferrer">KCP Protocol</a>, capable of transmitting arbitrary data streams in order.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to “Version”">​</a></h2><p>mKCP has no version number and does not guarantee compatibility between versions.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><h3 id="underlying-protocol" tabindex="-1">Underlying Protocol <a class="header-anchor" href="#underlying-protocol" aria-label="Permalink to “Underlying Protocol”">​</a></h3><p>mKCP is a UDP-based protocol; all communication is transmitted using UDP.</p><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h3><ul><li>fnv: <a href="https://en.wikipedia.org/wiki/Fowler%E2%80%93Noll%E2%80%93Vo_hash_function" target="_blank" rel="noreferrer">FNV-1a</a> hash function <ul><li>Input parameter is a string of arbitrary length;</li><li>Outputs a 32-bit unsigned integer;</li></ul></li></ul><h2 id="communication-process" tabindex="-1">Communication Process <a class="header-anchor" href="#communication-process" aria-label="Permalink to “Communication Process”">​</a></h2><ol><li>mKCP splits the data stream into several packets for transmission. A data stream has a unique identifier to distinguish different data streams. Every packet in a data stream carries the same identifier.</li><li>mKCP has no handshake process. When a packet is received, the identifier carried by it determines whether it is a new call or an ongoing one.</li><li>Each packet contains several segments. Segments are divided into three categories: Data, ACK (Acknowledgment), and Ping (Heartbeat). Each segment needs to be processed separately.</li></ol><h2 id="data-format" tabindex="-1">Data Format <a class="header-anchor" href="#data-format" aria-label="Permalink to “Data Format”">​</a></h2><h3 id="packet" tabindex="-1">Packet <a class="header-anchor" href="#packet" aria-label="Permalink to “Packet”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">L Bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Authentication A</td><td style="text-align:left;">Data Length L</td><td style="text-align:left;">Segment Part</td></tr></tbody></table><p>Where:</p><ul><li>Authentication A = fnv(Segment Part), big endian;</li><li>The Segment Part may contain multiple segments;</li></ul><h3 id="data-segment" tabindex="-1">Data Segment <a class="header-anchor" href="#data-segment" aria-label="Permalink to “Data Segment”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">Len Bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Identifier Conv</td><td style="text-align:left;">Command Cmd</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Timestamp Ts</td><td style="text-align:left;">Sequence Sn</td><td style="text-align:left;">Unacknowledged Una</td><td style="text-align:left;">Length Len</td><td style="text-align:left;">Data</td></tr></tbody></table><p>Where:</p><ul><li>Identifier Conv: The identifier of the mKCP data stream.</li><li>Command Cmd: Constant <code>0x01</code>.</li><li>Option Opt: Optional values are: <ul><li><code>0x00</code>: Empty option.</li><li><code>0x01</code>: The peer has sent all data.</li></ul></li><li>Timestamp Ts: The time when the current segment was sent from the remote end, big endian.</li><li>Sequence Sn: The position of this data segment in the data stream. The sequence number of the starting segment is 0, and each subsequent new segment increases by 1 in order.</li><li>Unacknowledged Una: The smallest Sn that the remote host is sending and has not yet received an acknowledgment for.</li></ul><h3 id="ack-segment" tabindex="-1">ACK Segment <a class="header-anchor" href="#ack-segment" aria-label="Permalink to “ACK Segment”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">Len * 4 Bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Identifier Conv</td><td style="text-align:left;">Command Cmd</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Window Wnd</td><td style="text-align:left;">Next Receive Sn</td><td style="text-align:left;">Timestamp Ts</td><td style="text-align:left;">Length Len</td><td style="text-align:left;">Received Sns</td></tr></tbody></table><p>Where:</p><ul><li>Identifier Conv: The identifier of the mKCP data stream.</li><li>Command Cmd: Constant <code>0x00</code>.</li><li>Option Opt: Same as above.</li><li>Window Wnd: The maximum sequence number the remote host can receive.</li><li>Next Receive Sn: The smallest sequence number among the data segments not yet received by the remote host.</li><li>Timestamp Ts: The timestamp of the latest data segment received by the remote host, used for calculating latency.</li><li>Received Sns: Each is 4 bytes, indicating that data with this sequence number has been confirmed as received.</li></ul><p>Note:</p><ul><li>The remote host expects to receive data within the sequence number range [Sn, Wnd).</li></ul><h3 id="ping-heartbeat-segment" tabindex="-1">Ping (Heartbeat) Segment <a class="header-anchor" href="#ping-heartbeat-segment" aria-label="Permalink to “Ping (Heartbeat) Segment”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 Bytes</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">1 Byte</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th><th style="text-align:left;">4 Bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Identifier Conv</td><td style="text-align:left;">Command Cmd</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Unacknowledged Una</td><td style="text-align:left;">Next Receive Sn</td><td style="text-align:left;">Latency Rto</td></tr></tbody></table><p>Where:</p><ul><li>Identifier Conv: The identifier of the mKCP data stream.</li><li>Command Cmd: Optional values are: <ul><li><code>0x02</code>: Remote host forcibly terminates the session.</li><li><code>0x03</code>: Normal heartbeat.</li></ul></li><li>Option Opt: Same as above.</li><li>Unacknowledged Una: Same as Una in the Data Segment.</li><li>Next Receive Sn: Same as Sn in the ACK Segment.</li><li>Latency Rto: The latency calculated by the remote host itself.</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};